import asyncio
import pygame, random, math, base64, io

pygame.init()
W,H=1100,650
screen=pygame.display.set_mode((W,H))
pygame.display.set_caption("Martelo da Esperança")
clock=pygame.time.Clock()

# ===== SPRITES EMBUTIDOS NO PYTHON =====
PLAYER_B64=""
ENEMY_B64=""
ATTACK_B64=""
GROUND_B64=""

def sprite(data,size):
    im=pygame.image.load(io.BytesIO(base64.b64decode(data))).convert_alpha()
    return pygame.transform.smoothscale(im,size)

PLAYER=sprite(PLAYER_B64,(90,105))
ENEMY=sprite(ENEMY_B64,(85,60))
ATTACK=sprite(ATTACK_B64,(145,125))
GROUND=sprite(GROUND_B64,(64,64))

WHITE=(245,245,245); RED=(220,55,65); BLUE=(60,150,240)
GREEN=(55,210,95); YELLOW=(245,205,70)

font=pygame.font.Font(None,30)
big=pygame.font.Font(None,58)

class Player:
    def __init__(self):
        self.x=W/2; self.y=H-105
        self.life=100; self.stamina=100
        self.attack_time=0; self.cooldown=0
    @property
    def rect(self):
        return pygame.Rect(self.x-23,self.y-70,46,70)
    def update(self,dt):
        keys=pygame.key.get_pressed(); d=0
        if keys[pygame.K_a] or keys[pygame.K_LEFT]: d-=1
        if keys[pygame.K_d] or keys[pygame.K_RIGHT]: d+=1
        run=(keys[pygame.K_LSHIFT] or keys[pygame.K_RSHIFT]) and d and self.stamina>0
        speed=390 if run else 250
        self.x+=d*speed*dt
        self.x=max(40,min(W-40,self.x))
        self.stamina=max(0,min(100,self.stamina-(34*dt if run else -24*dt)))
        self.attack_time=max(0,self.attack_time-dt)
        self.cooldown=max(0,self.cooldown-dt)
    def attack(self):
        if self.cooldown<=0:
            self.attack_time=.22; self.cooldown=.42
    def hitbox(self):
        return pygame.Rect(self.x-72,self.y-92,144,110) if self.attack_time>0 else None
    def draw(self):
        screen.blit(PLAYER,(self.x-45,self.y-105))
        if self.attack_time>0:
            screen.blit(ATTACK,(self.x+5,self.y-115))

class Enemy:
    def __init__(self,x,hp):
        self.x=x; self.y=H-105; self.hp=hp; self.maxhp=hp
        self.speed=random.randint(75,115); self.damage_cd=0
    @property
    def rect(self):
        return pygame.Rect(self.x-24,self.y-60,48,60)
    def update(self,dt):
        dx=player.x-self.x
        if abs(dx)>50: self.x+=(1 if dx>0 else -1)*self.speed*dt
        self.x=max(25,min(W-25,self.x))
        self.damage_cd=max(0,self.damage_cd-dt)
        if self.rect.colliderect(player.rect) and self.damage_cd<=0:
            player.life-=8; self.damage_cd=.8
    def draw(self):
        bx=self.x-32; by=self.y-80
        pygame.draw.rect(screen,(35,35,35),(bx,by,64,8))
        pygame.draw.rect(screen,GREEN,(bx,by,64*max(0,self.hp)/self.maxhp,8))
        screen.blit(ENEMY,(self.x-42,self.y-60))

player=Player()
enemies=[]; wave=0; kills=0; next_wave=0; wave_msg=0; game_over=False

def start_wave():
    global wave,enemies,wave_msg
    wave+=1
    hp=40+(wave-1)*12
    enemies=[Enemy(random.choice([random.randint(30,130),random.randint(W-130,W-30)]),hp)
              for _ in range(2+wave*2)]
    wave_msg=1.5

start_wave()

async def main():
    global kills, next_wave, game_over, wave_msg
    running=True
    while running:
        dt=clock.tick(60)/1000
        for e in pygame.event.get():
            if e.type==pygame.QUIT: running=False
            if e.type==pygame.KEYDOWN:
                if e.key==pygame.K_ESCAPE: running=False
                if e.key==pygame.K_SPACE and not game_over: player.attack()

        if not game_over:
            player.update(dt)
            for enemy in enemies[:]: enemy.update(dt)
            box=player.hitbox()
            if box:
                for enemy in enemies[:]:
                    if box.colliderect(enemy.rect):
                        enemy.hp-=25
                        if enemy.hp<=0:
                            enemies.remove(enemy); kills+=1
            if not enemies:
                next_wave+=dt
                if next_wave>=1.2: next_wave=0; start_wave()
            else: next_wave=0
            if player.life<=0: player.life=0; game_over=True
            wave_msg=max(0,wave_msg-dt)

        # terreno
        screen.fill((22,58,38))
        for x in range(0,W,64):
            screen.blit(GROUND,(x,H-90))
        pygame.draw.rect(screen,(92,67,43),(0,H-100,W,15))

        for enemy in enemies: enemy.draw()
        player.draw()

        screen.blit(big.render(f"ONDA {wave}",True,YELLOW),(20,15))
        screen.blit(font.render(f"KILLS: {kills}",True,WHITE),(20,72))
        screen.blit(font.render("VIDA",True,WHITE),(20,108))
        pygame.draw.rect(screen,(35,35,35),(80,111,220,21))
        pygame.draw.rect(screen,RED,(80,111,220*player.life/100,21))
        screen.blit(font.render("ESTAMINA",True,WHITE),(20,143))
        pygame.draw.rect(screen,(35,35,35),(120,146,180,17))
        pygame.draw.rect(screen,BLUE,(120,146,180*player.stamina/100,17))
        screen.blit(font.render("A/D ou SETAS: mover | SHIFT: correr | ESPAÇO: atacar",True,WHITE),(20,H-34))

        if wave_msg:
            t=big.render(f"ONDA {wave}",True,YELLOW)
            screen.blit(t,(W//2-t.get_width()//2,40))

        if game_over:
            overlay=pygame.Surface((W,H),pygame.SRCALPHA); overlay.fill((0,0,0,175))
            screen.blit(overlay,(0,0))
            t=big.render("VOCÊ FOI DERROTADO!",True,RED)
            screen.blit(t,(W//2-t.get_width()//2,H//2-60))
            screen.blit(font.render(f"Ondas: {wave} | Kills: {kills}",True,WHITE),(W//2-100,H//2+5))

        pygame.display.flip()
        await asyncio.sleep(0)

    pygame.quit()


asyncio.run(main())
